{% extends "base.html" %}
{% block title %}ወሎየዋ ሱቅ — Home{% endblock %}

{% block content %}
<header class="page-header">
    <h1>ወሎየዋ ሱቅ 🇪🇹</h1>
    <p class="subtitle">Ethiopian Online Store</p>
</header>

<div class="search-bar">
    <input type="text" id="search-input" placeholder="Search products..." oninput="filterProducts()">
</div>

<section class="featured-section">
    <h2 class="section-title">Featured Products</h2>
    <div id="products-grid" class="products-grid">
        <div class="loading-spinner">Loading products…</div>
    </div>
</section>
{% endblock %}

{% block scripts %}
<script>
let allProducts = [];

async function loadProducts() {
    try {
        const res = await fetch('/app/api/products?page_size=40');
        const data = await res.json();
        allProducts = data.items || [];
        renderProducts(allProducts);
    } catch (e) {
        document.getElementById('products-grid').innerHTML = '<p class="empty-state">Could not load products.</p>';
    }
}

function renderProducts(products) {
    const grid = document.getElementById('products-grid');
    if (!products.length) {
        grid.innerHTML = '<p class="empty-state">No products available yet.</p>';
        return;
    }
    grid.innerHTML = products.map(p => `
        <a href="/app/product/${p.id}" class="product-card">
            <div class="product-img">
                ${p.images && p.images[0] ? `<img src="${safeUrl(p.images[0])}" alt="" loading="lazy">` : '<span class="img-placeholder">📦</span>'}
            </div>
            <div class="product-info">
                <p class="product-name">${he(p.name)}</p>
                <p class="product-price">ETB ${Number(p.price || 0).toLocaleString()}</p>
                ${p.stock_quantity <= 0 ? '<span class="out-of-stock">Out of stock</span>' : ''}
            </div>
        </a>
    `).join('');
}

function filterProducts() {
    const q = document.getElementById('search-input').value.toLowerCase();
    renderProducts(allProducts.filter(p => p.name && p.name.toLowerCase().includes(q)));
}

loadProducts();
updateCartBadge();
</script>
{% endblock %}

{% extends "base.html" %}
{% block title %}Categories — ወሎየዋ ሱቅ{% endblock %}

{% block content %}
<header class="page-header">
    <h1>Categories</h1>
</header>

<div id="categories-list" class="categories-grid">
    <div class="loading-spinner">Loading…</div>
</div>
{% endblock %}

{% block scripts %}
<script>
async function loadCategories() {
    try {
        const res = await fetch('/app/api/categories');
        const cats = await res.json();
        const el = document.getElementById('categories-list');
        if (!cats.length) {
            el.innerHTML = '<p class="empty-state">No categories yet.</p>';
            return;
        }
        el.innerHTML = cats.map(c => `
            <a href="/app/?category=${c.id}" class="category-card">
                <div class="category-icon">${c.icon_url ? `<img src="${safeUrl(c.icon_url)}" alt="">` : '📁'}</div>
                <p class="category-name">${he(c.name)}</p>
                ${c.name_am ? `<p class="category-name-am">${he(c.name_am)}</p>` : ''}
                <p class="product-count">${c.product_count} products</p>
            </a>
        `).join('');
    } catch (e) {
        document.getElementById('categories-list').innerHTML = '<p class="empty-state">Could not load categories.</p>';
    }
}

loadCategories();
updateCartBadge();
</script>
{% endblock %}

{% extends "base.html" %}
{% block title %}Product — ወሎየዋ ሱቅ{% endblock %}

{% block content %}
<div class="back-bar">
    <button onclick="history.back()" class="btn-back">← Back</button>
</div>

<div id="product-detail" class="product-detail">
    <div class="loading-spinner">Loading product…</div>
</div>
{% endblock %}

{% block scripts %}
<script>
const productId = {{ product_id }};

async function loadProduct() {
    try {
        const res = await fetch(`/app/api/product/${productId}`);
        if (!res.ok) throw new Error('Not found');
        const p = await res.json();
        const el = document.getElementById('product-detail');
        el.innerHTML = `
            <div class="product-images">
                ${p.images && p.images[0] ? `<img src="${safeUrl(p.images[0])}" alt="" class="product-main-img">` : '<div class="img-placeholder large">📦</div>'}
            </div>
            <div class="product-body">
                <h1 class="product-title">${he(p.name)}</h1>
                ${p.name_am ? `<p class="product-title-am">${he(p.name_am)}</p>` : ''}
                <p class="product-price-large">ETB ${Number(p.price || 0).toLocaleString()}</p>
                ${p.original_price && p.original_price > p.price ? `<p class="product-original-price">ETB ${Number(p.original_price).toLocaleString()}</p>` : ''}
                <p class="product-stock ${p.stock_quantity > 0 ? 'in-stock' : 'out-of-stock'}">
                    ${p.stock_quantity > 0 ? `✅ In Stock (${p.stock_quantity})` : '❌ Out of Stock'}
                </p>
                ${p.description ? `<div class="product-desc">${he(p.description)}</div>` : ''}
                <div class="qty-row">
                    <button onclick="changeQty(-1)" class="btn-qty">−</button>
                    <span id="qty">1</span>
                    <button onclick="changeQty(1)" class="btn-qty">+</button>
                </div>
                <button onclick="addToCart(${p.id}, ${JSON.stringify(he(p.name))}, ${p.price})"
                    class="btn-primary" ${p.stock_quantity <= 0 ? 'disabled' : ''}>
                    🛒 Add to Cart
                </button>
            </div>
        `;
    } catch (e) {
        document.getElementById('product-detail').innerHTML = '<p class="empty-state">Product not found.</p>';
    }
}

function changeQty(delta) {
    const el = document.getElementById('qty');
    const v = Math.max(1, parseInt(el.textContent) + delta);
    el.textContent = v;
}

function addToCart(id, name, price) {
    const qty = parseInt(document.getElementById('qty').textContent);
    const cart = JSON.parse(localStorage.getItem('cart') || '[]');
    const existing = cart.find(i => i.id === id);
    if (existing) existing.qty += qty;
    else cart.push({ id, name, price, qty });
    localStorage.setItem('cart', JSON.stringify(cart));
    updateCartBadge();
    if (window.Telegram && window.Telegram.WebApp) {
        window.Telegram.WebApp.showAlert('Added to cart!');
    } else {
        alert('Added to cart!');
    }
}

loadProduct();
updateCartBadge();
</script>
{% endblock %}

{% extends "base.html" %}
{% block title %}Cart — ወሎየዋ ሱቅ{% endblock %}

{% block content %}
<header class="page-header">
    <h1>🛒 Your Cart</h1>
</header>

<div id="cart-container"></div>

<div id="cart-footer" class="cart-footer" style="display:none">
    <div class="cart-total-row">
        <span>Total:</span>
        <strong id="cart-total">ETB 0</strong>
    </div>
    <a href="/app/checkout" class="btn-primary btn-block">Proceed to Checkout</a>
</div>
{% endblock %}

{% block scripts %}
<script>
function renderCart() {
    const cart = JSON.parse(localStorage.getItem('cart') || '[]');
    const el = document.getElementById('cart-container');
    const footer = document.getElementById('cart-footer');

    if (!cart.length) {
        el.innerHTML = '<p class="empty-state">Your cart is empty.<br><a href="/app/">Browse products →</a></p>';
        footer.style.display = 'none';
        return;
    }

    let total = 0;
    el.innerHTML = cart.map((item, idx) => {
        const subtotal = item.price * item.qty;
        total += subtotal;
        return `
        <div class="cart-item">
            <div class="cart-item-info">
                <p class="cart-item-name">${he(item.name)}</p>
                <p class="cart-item-price">ETB ${Number(item.price).toLocaleString()} × ${item.qty}</p>
            </div>
            <div class="cart-item-controls">
                <p class="cart-item-subtotal">ETB ${Number(subtotal).toLocaleString()}</p>
                <button onclick="removeItem(${idx})" class="btn-remove">🗑</button>
            </div>
        </div>`;
    }).join('');

    document.getElementById('cart-total').textContent = 'ETB ' + Number(total).toLocaleString();
    footer.style.display = 'block';
    updateCartBadge();
}

function removeItem(idx) {
    const cart = JSON.parse(localStorage.getItem('cart') || '[]');
    cart.splice(idx, 1);
    localStorage.setItem('cart', JSON.stringify(cart));
    renderCart();
}

renderCart();
</script>
{% endblock %}

{% extends "base.html" %}
{% block title %}Checkout — ወሎየዋ ሱቅ{% endblock %}

{% block content %}
<header class="page-header">
    <h1>Checkout</h1>
</header>

<form id="checkout-form" class="checkout-form" onsubmit="submitOrder(event)">
    <section class="form-section">
        <h2>Delivery Details</h2>
        <div class="form-group">
            <label>Full Name</label>
            <input type="text" id="full-name" required placeholder="Your full name">
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" id="phone" required placeholder="+251...">
        </div>
        <div class="form-group">
            <label>City</label>
            <input type="text" id="city" required placeholder="Addis Ababa">
        </div>
        <div class="form-group">
            <label>Address</label>
            <textarea id="address" required placeholder="Street, Sub-city, Woreda"></textarea>
        </div>
    </section>

    <section class="form-section">
        <h2>Payment Method</h2>
        <div class="payment-options">
            <label class="payment-option"><input type="radio" name="payment" value="chapa" checked> 🏦 Chapa</label>
            <label class="payment-option"><input type="radio" name="payment" value="telebirr"> 📱 Telebirr</label>
            <label class="payment-option"><input type="radio" name="payment" value="cbe"> 🏛️ CBE Birr</label>
            <label class="payment-option"><input type="radio" name="payment" value="cod"> 💵 Cash on Delivery</label>
        </div>
    </section>

    <section class="form-section">
        <h2>Order Summary</h2>
        <div id="order-summary"></div>
        <div class="cart-total-row">
            <span>Total:</span>
            <strong id="order-total">ETB 0</strong>
        </div>
    </section>

    <p id="checkout-error" class="error-msg" style="display:none"></p>
    <button type="submit" class="btn-primary btn-block" id="submit-btn">Place Order</button>
</form>

<div id="success-screen" class="success-screen" style="display:none">
    <div class="success-icon">✅</div>
    <h2>Order Placed!</h2>
    <p id="success-order-number"></p>
    <p>You'll receive a Telegram confirmation shortly.</p>
    <a href="/app/" class="btn-primary">Continue Shopping</a>
</div>
{% endblock %}

{% block scripts %}
<script>
function renderSummary() {
    const cart = JSON.parse(localStorage.getItem('cart') || '[]');
    const el = document.getElementById('order-summary');
    let total = 0;
    el.innerHTML = cart.map(i => {
        const sub = i.price * i.qty;
        total += sub;
        return `<div class="summary-row"><span>${he(i.name)} × ${i.qty}</span><span>ETB ${Number(sub).toLocaleString()}</span></div>`;
    }).join('');
    const shipping = total >= 1000 ? 0 : 50;
    total += shipping;
    if (shipping > 0) el.innerHTML += `<div class="summary-row"><span>Shipping</span><span>ETB ${shipping}</span></div>`;
    document.getElementById('order-total').textContent = 'ETB ' + Number(total).toLocaleString();
}

async function submitOrder(e) {
    e.preventDefault();
    const cart = JSON.parse(localStorage.getItem('cart') || '[]');
    if (!cart.length) { showError('Your cart is empty.'); return; }

    const btn = document.getElementById('submit-btn');
    btn.disabled = true;
    btn.textContent = 'Placing order…';
    document.getElementById('checkout-error').style.display = 'none';

    const payment_method = document.querySelector('input[name="payment"]:checked').value;
    const init_data = window.Telegram?.WebApp?.initData || '';

    try {
        const res = await fetch('/app/api/checkout', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                init_data,
                items: cart.map(i => ({ id: i.id, name: i.name, price: i.price, qty: i.qty })),
                full_name: document.getElementById('full-name').value,
                phone: document.getElementById('phone').value,
                city: document.getElementById('city').value,
                address: document.getElementById('address').value,
                payment_method,
            }),
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.detail || 'Order failed');

        localStorage.removeItem('cart');
        document.getElementById('checkout-form').style.display = 'none';
        document.getElementById('success-screen').style.display = 'flex';
        document.getElementById('success-order-number').textContent = 'Order #' + data.order_number;
        updateCartBadge();
    } catch (err) {
        showError(err.message);
        btn.disabled = false;
        btn.textContent = 'Place Order';
    }
}

function showError(msg) {
    const el = document.getElementById('checkout-error');
    el.textContent = msg;
    el.style.display = 'block';
}

renderSummary();
updateCartBadge();
</script>
{% endblock %}

{% extends "base.html" %}
{% block title %}My Orders — ወሎየዋ ሱቅ{% endblock %}

{% block content %}
<header class="page-header">
    <h1>📦 My Orders</h1>
</header>

<div id="orders-list">
    <div class="loading-spinner">Loading orders…</div>
</div>
{% endblock %}

{% block scripts %}
<script>
const STATUS_ICONS = {
    pending:    '⏳', confirmed: '✅', processing: '⚙️',
    shipped:    '🚚', delivered: '📬', cancelled:  '❌', refunded: '↩️',
};

async function loadOrders() {
    const init_data = window.Telegram?.WebApp?.initData || '';
    const el = document.getElementById('orders-list');
    try {
        const res = await fetch('/app/api/my-orders', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ init_data }),
        });
        const data = await res.json();
        if (!res.ok) {
            el.innerHTML = '<p class="empty-state">Please open this page from Telegram to see your orders.</p>';
            return;
        }
        const orders = data.orders || [];
        if (!orders.length) {
            el.innerHTML = '<p class="empty-state">No orders yet.<br><a href="/app/">Start shopping →</a></p>';
            return;
        }
        el.innerHTML = orders.map(o => `
            <div class="order-card">
                <div class="order-header">
                    <span class="order-number">#${he(o.order_number)}</span>
                    <span class="order-status">${STATUS_ICONS[o.status] || '📋'} ${he(o.status)}</span>
                </div>
                <p class="order-date">${o.created_at ? new Date(o.created_at).toLocaleDateString() : ''}</p>
                <div class="order-items-list">
                    ${(o.items || []).map(i => `<span class="order-item-chip">${he(i.name)} ×${i.quantity}</span>`).join('')}
                </div>
                <div class="order-footer">
                    <span class="order-total">ETB ${Number(o.total).toLocaleString()}</span>
                    ${o.tracking_number ? `<span class="tracking">🔍 ${he(o.tracking_number)}</span>` : ''}
                </div>
            </div>
        `).join('');
    } catch (e) {
        el.innerHTML = '<p class="empty-state">Could not load orders.</p>';
    }
}

loadOrders();
updateCartBadge();
</script>
{% endblock %}

{% extends "base.html" %}
{% block title %}Dashboard — ወሎየዋ ሱቅ{% endblock %}

{% block content %}
<header class="page-header">
    <h1>📊 Dashboard</h1>
</header>

<div id="health-status" class="dashboard-section">
    <div class="loading-spinner">Loading system status…</div>
</div>

<div class="dashboard-section">
    <h2>Quick Links</h2>
    <div class="quick-links">
        <a href="/api/docs" class="quick-link-card">📖 API Docs</a>
        <a href="/health" class="quick-link-card">❤️ Health Check</a>
        <a href="/app/" class="quick-link-card">🏠 Store Home</a>
        <a href="/app/orders" class="quick-link-card">📦 Orders</a>
    </div>
</div>

<div class="dashboard-section">
    <h2>Store Stats</h2>
    <div id="stats-grid" class="stats-grid">
        <div class="loading-spinner">Loading stats…</div>
    </div>
</div>
{% endblock %}

{% block scripts %}
<script>
async function loadHealth() {
    try {
        const res = await fetch('/health');
        const data = await res.json();
        const el = document.getElementById('health-status');
        const statusClass = data.status === 'healthy' ? 'status-healthy' : 'status-degraded';
        el.innerHTML = `
            <h2>System Status <span class="status-badge ${statusClass}">${data.status}</span></h2>
            <div class="health-checks">
                ${(data.checks || []).map(c => `
                    <div class="health-check-row">
                        <span>${c.status === 'healthy' ? '✅' : '⚠️'} ${he(c.name)}</span>
                        <span class="check-msg">${he(c.message)}</span>
                        <span class="check-time">${c.response_time_ms ? c.response_time_ms.toFixed(1) + 'ms' : ''}</span>
                    </div>
                `).join('')}
            </div>
        `;
    } catch (e) {
        document.getElementById('health-status').innerHTML = '<p class="empty-state">Could not load health status.</p>';
    }
}

async function loadStats() {
    try {
        const [prodRes, catRes] = await Promise.all([
            fetch('/app/api/products?page_size=1'),
            fetch('/app/api/categories'),
        ]);
        const prodData = await prodRes.json();
        const catData = await catRes.json();
        document.getElementById('stats-grid').innerHTML = `
            <div class="stat-card"><div class="stat-value">${prodData.total || 0}</div><div class="stat-label">Products</div></div>
            <div class="stat-card"><div class="stat-value">${catData.length || 0}</div><div class="stat-label">Categories</div></div>
        `;
    } catch (e) {
        document.getElementById('stats-grid').innerHTML = '<p class="empty-state">Could not load stats.</p>';
    }
}

loadHealth();
loadStats();
updateCartBadge();
</script>
{% endblock %}

