    41→    const badge = document.querySelector('.cart-badge');
    42→    if (badge) {
    43→      const c = this.count();
    44→      badge.textContent = c;
    45→      badge.style.display = c > 0 ? 'inline' : 'none';
    46→    }
    47→  }
    48→};
    49→
    50→// Init badge on load
    51→document.addEventListener('DOMContentLoaded', () => cart.updateBadge());
    52→
    53→// Toast notification
    54→function showToast(msg, duration = 2500) {
    55→  let toast = document.getElementById('toast');
    56→  if (!toast) {
    57→    toast = document.createElement('div');
    58→    toast.id = 'toast';
    59→    toast.className = 'toast';
    60→    document.body.appendChild(toast);
    61→  }
    62→  toast.textContent = msg;
    63→  toast.classList.add('show');
    64→  setTimeout(() => toast.classList.remove('show'), duration);
    65→}
    66→
    67→// Format ETB currency
    68→function formatPrice(amount) {
    69→  return 'ETB ' + Number(amount).toLocaleString('en-ET', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    70→}
    71→
    72→// HTML-escape untrusted strings before injecting into innerHTML
    73→function he(str) {
    74→  if (str == null) return '';
    75→  return String(str)
    76→    .replace(/&/g, '&amp;')
    77→    .replace(/</g, '&lt;')
    78→    .replace(/>/g, '&gt;')
    79→    .replace(/"/g, '&quot;')
    80→    .replace(/'/g, '&#39;');
    81→}
    82→
    83→// Validate a URL is safe (http/https only) before using in src/href
    84→function safeUrl(url) {
    85→  if (!url) return '';
    86→  try {
    87→    const u = new URL(url);
    88→    return (u.protocol === 'http:' || u.protocol === 'https:') ? url : '';
    89→  } catch { return ''; }
    90→}
    91→
    92→window.he = he;
    93→window.safeUrl = safeUrl;
