   104→  sports: '⚽',
   105→  default: '🛍️'
   106→};
   107→
   108→function getCategoryEmoji(cat) {
   109→  if (!cat) return categoryEmoji.default;
   110→  const k = cat.toLowerCase();
   111→  return categoryEmoji[k] || categoryEmoji.default;
   112→}
   113→
   114→// Fetch products from API
   115→async function fetchProducts(params = {}) {
