   139→  display: flex; align-items: center;
   140→  gap: 10px; height: 56px;
   141→}
   142→.hamburger-btn {
   143→  background: none; border: none;
   144→  font-size: 22px; cursor: pointer;
   145→  padding: 6px 8px;
   146→  color: var(--text);
   147→  border-radius: 8px;
