   181→.nav-btn {
   182→  display: flex; align-items: center; gap: 6px;
   183→  padding: 8px 14px; border-radius: 8px;
   184→  font-size: 14px; font-weight: 500;
   185→  text-decoration: none; border: none; cursor: pointer;
   186→  transition: background 0.2s;
   187→}
   188→.nav-btn-primary { background: var(--primary); color: var(--white); }
   189→.nav-btn-primary:hover { background: var(--primary-dark); }
   190→.nav-btn-ghost { background: transparent; color: var(--text); }
   191→.nav-btn-ghost:hover { background: var(--bg); }
   192→.cart-badge {
   193→  background: var(--danger); color: white;
   194→  border-radius: 999px; font-size: 11px;
   195→  padding: 1px 6px; font-weight: 700;
   196→}
   197→
   198→/* ═══════════════════════════════════════════
   199→   BOTTOM NAVIGATION BAR
   200→═══════════════════════════════════════════ */
   201→.bottom-nav {
   202→  position: fixed; bottom: 0; left: 0; right: 0;
   203→  height: var(--bnav-h);
   204→  background: var(--white);
   205→  border-top: 1px solid var(--border);
   206→  display: flex; align-items: stretch;
   207→  z-index: 150;
   208→  box-shadow: 0 -2px 14px rgba(0,0,0,0.06);
   209→}
   210→.bnav-item {
   211→  flex: 1; display: flex; flex-direction: column;
   212→  align-items: center; justify-content: center;
   213→  text-decoration: none; color: var(--text-muted);
   214→  gap: 2px; position: relative;
   215→  transition: color 0.2s, background 0.15s;
   216→  padding: 8px 4px calc(8px + env(safe-area-inset-bottom, 0px));
   217→}
   218→.bnav-item:hover { background: var(--primary-light); color: var(--primary); }
   219→.bnav-item.active { color: var(--primary); }
   220→.bnav-item.active::before {
   221→  content: '';
   222→  position: absolute; top: 0; left: 50%;
   223→  transform: translateX(-50%);
   224→  width: 32px; height: 3px;
   225→  background: var(--primary);
   226→  border-radius: 0 0 4px 4px;
   227→}
   228→.bnav-icon-wrap { position: relative; display: inline-flex; }
   229→.bnav-icon { font-size: 22px; line-height: 1; }
   230→.bnav-badge {
   231→  position: absolute; top: -5px; right: -10px;
   232→  background: var(--danger); color: white;
   233→  border-radius: 999px; font-size: 9px;
   234→  min-width: 16px; height: 16px;
   235→  display: none; align-items: center; justify-content: center;
   236→  font-weight: 700; border: 2px solid var(--white);
