   238→}
   239→.bnav-badge.show { display: flex; }
   240→.bnav-label { font-size: 10px; font-weight: 600; letter-spacing: 0.2px; }
   241→
   242→/* ═══════════════════════════════════════════
   243→   PROMOTIONAL BANNER
   244→═══════════════════════════════════════════ */
   245→.promo-section {
   246→  max-width: 1100px; margin: 24px auto 0;
   247→  padding: 0 16px;
   248→  display: grid;
   249→  grid-template-columns: 1fr 1fr;
   250→  gap: 14px;
   251→}
   252→.promo-card {
   253→  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
   254→  border-radius: var(--radius);
   255→  padding: 20px 24px; color: white;
   256→  display: flex; align-items: center;
   257→  justify-content: space-between; gap: 16px;
   258→  overflow: hidden; position: relative;
