   268→.promo-text { z-index: 1; }
   269→.promo-text h3 { font-size: 15px; font-weight: 800; margin-bottom: 4px; line-height: 1.3; }
   270→.promo-text p { font-size: 12px; opacity: 0.85; }
   271→.promo-btn {
   272→  background: rgba(255,255,255,0.95); color: var(--primary);
   273→  border: none; border-radius: 999px;
   274→  padding: 8px 16px; font-size: 12px; font-weight: 700;
   275→  cursor: pointer; white-space: nowrap; z-index: 1;
