   279→.promo-card.promo-gold .promo-btn { color: #92400e; }
   280→
   281→/* ═══════════════════════════════════════════
   282→   HERO
   283→═══════════════════════════════════════════ */
   284→.hero {
   285→  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
   286→  color: white; padding: 48px 16px; text-align: center;
