   298→
   299→/* ═══════════════════════════════════════════
   300→   CATEGORIES
   301→═══════════════════════════════════════════ */
   302→.section { max-width: 1100px; margin: 0 auto; padding: 32px 16px; }
   303→.section-title {
   304→  font-size: 20px; font-weight: 700; margin-bottom: 18px;
   305→  display: flex; align-items: center; gap: 8px;
   306→}
   307→.category-grid {
   308→  display: grid;
   309→  grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
   310→  gap: 12px; margin-bottom: 8px;
   311→}
   312→.category-card {
   313→  background: var(--white); border: 1px solid var(--border);
   314→  border-radius: var(--radius);
   315→  padding: 16px 8px; text-align: center;
   316→  cursor: pointer; transition: all 0.2s;
   317→  text-decoration: none; color: var(--text);
   318→}
   319→.category-card:hover, .category-card.active {
   320→  border-color: var(--primary);
   321→  background: var(--primary-light);
   322→  color: var(--primary);
   323→}
   324→.category-card .icon { font-size: 28px; margin-bottom: 6px; }
