   326→
   327→/* ═══════════════════════════════════════════
   328→   PRODUCTS
   329→═══════════════════════════════════════════ */
   330→.products-grid {
   331→  display: grid;
   332→  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
   333→  gap: 18px;
   334→}
   335→.product-card {
