   346→}
   347→.product-image {
   348→  width: 100%; aspect-ratio: 1; object-fit: cover;
   349→  background: var(--bg);
   350→  display: flex; align-items: center; justify-content: center;
   351→  font-size: 56px;
   352→}
   353→.product-info { padding: 14px; flex: 1; display: flex; flex-direction: column; }
   354→.product-name { font-size: 14px; font-weight: 600; margin-bottom: 4px; line-height: 1.4; }
   355→.product-desc { font-size: 12px; color: var(--text-muted); margin-bottom: 10px; flex: 1; }
   356→.product-footer { display: flex; align-items: center; justify-content: space-between; margin-top: auto; }
   357→.product-price { font-size: 16px; font-weight: 800; color: var(--primary); }
