   366→
   367→/* ═══════════════════════════════════════════
   368→   PRODUCT DETAIL
   369→═══════════════════════════════════════════ */
   370→.product-detail { max-width: 900px; margin: 32px auto; padding: 0 16px; }
   371→.product-detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; }
   372→.product-detail-image {
   373→  background: var(--white); border: 1px solid var(--border);
