   378→.product-detail-info { display: flex; flex-direction: column; gap: 16px; }
   379→.product-detail-name { font-size: 26px; font-weight: 800; line-height: 1.3; }
   380→.product-detail-price { font-size: 32px; font-weight: 800; color: var(--primary); }
   381→.product-detail-desc { font-size: 15px; color: var(--text-muted); line-height: 1.7; }
   382→.qty-control { display: flex; align-items: center; gap: 12px; }
   383→.qty-btn {
   384→  width: 36px; height: 36px;
   385→  border: 1px solid var(--border); border-radius: 8px;
   386→  font-size: 18px; font-weight: 700;
   387→  background: var(--white); cursor: pointer;
