   391→.qty-btn:hover { background: var(--bg); }
   392→.qty-value { font-size: 18px; font-weight: 700; min-width: 32px; text-align: center; }
   393→.btn-primary {
   394→  background: var(--primary); color: white; border: none;
   395→  border-radius: var(--radius); padding: 14px 28px;
   396→  font-size: 16px; font-weight: 700; cursor: pointer;
   397→  width: 100%; transition: background 0.2s;
   398→  text-decoration: none; display: block; text-align: center;
   399→}
   400→.btn-primary:hover { background: var(--primary-dark); }
   401→.badge {
   402→  display: inline-flex; align-items: center; gap: 4px;
   403→  padding: 4px 10px; border-radius: 999px; font-size: 12px; font-weight: 600;
   404→}
   405→.badge-green { background: var(--primary-light); color: var(--primary); }
   406→.badge-red { background: #fee2e2; color: var(--danger); }
   407→
   408→/* ═══════════════════════════════════════════
   409→   CART PAGE
   410→═══════════════════════════════════════════ */
   411→.cart-page { max-width: 800px; margin: 32px auto; padding: 0 16px; }
   412→.cart-empty { text-align: center; padding: 64px 16px; color: var(--text-muted); }
   413→.cart-empty .icon { font-size: 64px; margin-bottom: 16px; }
   414→.cart-item {
   415→  background: var(--white); border: 1px solid var(--border);
   416→  border-radius: var(--radius); padding: 16px;
   417→  display: flex; gap: 16px; align-items: center; margin-bottom: 12px;
   418→}
   419→.cart-item-img { font-size: 40px; flex-shrink: 0; }
