   424→.btn-remove { background: #fee2e2; color: var(--danger); border: none; border-radius: 8px; padding: 6px 10px; cursor: pointer; font-size: 13px; }
   425→.cart-summary {
   426→  background: var(--white); border: 1px solid var(--border);
   427→  border-radius: var(--radius); padding: 20px; margin-top: 16px;
   428→}
   429→.cart-summary-row { display: flex; justify-content: space-between; margin-bottom: 10px; font-size: 15px; }
   430→.cart-summary-row.total {
   431→  font-weight: 800; font-size: 18px;
   432→  border-top: 1px solid var(--border); padding-top: 10px; margin-top: 4px;
   433→}
   434→
   435→/* ═══════════════════════════════════════════
   436→   CHECKOUT
   437→═══════════════════════════════════════════ */
   438→.checkout-page { max-width: 700px; margin: 32px auto; padding: 0 16px; }
   439→.form-card {
   440→  background: var(--white); border: 1px solid var(--border);
   441→  border-radius: var(--radius); padding: 24px; margin-bottom: 20px;
   442→}
   443→.form-card h2 { font-size: 17px; font-weight: 700; margin-bottom: 18px; }
   444→.form-group { margin-bottom: 16px; }
