   462→.payment-option.selected { border-color: var(--primary); background: var(--primary-light); }
   463→.payment-option input[type=radio] { accent-color: var(--primary); }
   464→.payment-icon { font-size: 24px; }
   465→.payment-label { font-size: 14px; font-weight: 600; }
   466→.payment-sub { font-size: 12px; color: var(--text-muted); }
   467→
   468→/* ═══════════════════════════════════════════
   469→   ALERTS & TOAST
   470→═══════════════════════════════════════════ */
   471→.alert { padding: 12px 16px; border-radius: 8px; font-size: 14px; margin-bottom: 12px; }
   472→.alert-success { background: var(--primary-light); color: var(--primary); border: 1px solid #a7f3c5; }
   473→.alert-error { background: #fee2e2; color: var(--danger); border: 1px solid #fca5a5; }
   474→
   475→.toast {
   476→  position: fixed;
   477→  bottom: calc(var(--bnav-h) + 14px);
   478→  left: 50%; transform: translateX(-50%);
   479→  background: var(--text); color: white;
   480→  padding: 12px 24px; border-radius: 999px;
   481→  font-size: 14px; font-weight: 500;
