   483→  transition: opacity 0.3s; pointer-events: none;
   484→  white-space: nowrap;
   485→}
   486→.toast.show { opacity: 1; }
   487→
   488→/* ═══════════════════════════════════════════
   489→   RICH FOOTER
   490→═══════════════════════════════════════════ */
