   539→  text-decoration: none; font-size: 12px; font-weight: 600;
   540→  transition: background 0.2s, color 0.2s;
   541→}
   542→.fsoc-btn:hover { background: var(--primary); color: white; border-color: var(--primary); }
   543→.footer-bottom p { font-size: 12px; color: rgba(255,255,255,0.35); }
   544→
   545→/* Legacy .footer (fallback) */
