   547→  background: var(--white); border-top: 1px solid var(--border);
   548→  text-align: center; padding: 20px;
   549→  color: var(--text-muted); font-size: 13px; margin-top: 48px;
   550→}
   551→
   552→/* ═══════════════════════════════════════════
   553→   ORDER CARDS (orders page)
   554→═══════════════════════════════════════════ */
   555→.orders-list { display: flex; flex-direction: column; gap: 14px; padding: 0 16px 32px; }
   556→.order-card {
   557→  background: var(--surface); border: 1.5px solid var(--border);
   558→  border-radius: var(--radius); overflow: hidden;
   559→  transition: box-shadow 0.2s;
   560→}
