<!-- ── Products ─────────────────────────────────────────── -->
<div class="section">
    <div class="section-title">🛒 ምርቶቸ</div>
    <div class="products-grid" id="productsGrid" style="grid-template-columns:repeat(2,1fr);gap:12px">
        <div class="loading-spinner" style="grid-column:1/-1;text-align:center;padding:40px;color:var(--text-muted)">
            ምርቶቸ እየጫናን ነው…
        </div>
    </div>
    <div id="loadMoreWrap" style="text-align:center;margin-top:18px;display:none">
        <button id="loadMoreBtn" onclick="loadMore()" class="btn-primary" style="width:auto;padding:12px 36px">
            ተጨማሪ ምርቶቸ
        </button>
    </div>
</div>

{% endblock %}

{% block scripts %}
<script>
const CAT_ICONS = {
    'electronics':'📱','clothing':'👕','food':'🍎','food & drinks':'🍎',
    'books':'📚','beauty':'💄','health':'💊','home':'🏠','home & living':'🏠',
    'sports':'⚽','toys':'🧸','automotive':'🚗','agriculture':'🌾','all':'🛍️',
};
function catIcon(name) {
    if (!name) return '🛍️';
    const k = name.toLowerCase();
    return CAT_ICONS[k] || Object.keys(CAT_ICONS).reduce((found, key) => {
        return (!found && k.includes(key)) ? CAT_ICONS[key] : found;
    }, '') || '🛍️';
}

let allProducts = [];
let filteredProducts = [];
let activeCatId = null;
let displayPage = 1;
const PAGE_SIZE = 20;

// ── Load categories for the mini-row ──────────────────────────
async function loadHomeCats() {
    try {
        const cats = await fetch('/app/api/categories').then(r => r.json());
        const grid = document.getElementById('homeCatGrid');
        const items = [{ id: null, name: 'ሁሉ', name_am: 'All' }, ...cats];
        grid.innerHTML = items.map(c => `
            <div class="category-card ${c.id === null ? 'active' : ''}" onclick="filterByCat(${c.id},this)">
                <div class="icon">${catIcon(c.name)}</div>
                <div class="label">${he(c.name_am || c.name)}</div>
            </div>
        `).join('');
    } catch(e) {
        document.getElementById('homeCatGrid').innerHTML = '';
    }
}

// ── Load all products ──────────────────────────────────────────
async function loadProducts() {
    try {
        const data = await fetch('/app/api/products?page_size=200').then(r => r.json());
        allProducts = data.items || [];
        filteredProducts = allProducts;
        renderProductsPage();
    } catch(e) {
        document.getElementById('productsGrid').innerHTML =
            '<p class="empty-state" style="grid-column:1/-1;text-align:center;padding:40px;color:var(--text-muted)">ምርቶቸ መጫን አልተቻለም።</p>';
    }
}

// ── Render current page of products ────────────────────────────
function renderProductsPage(reset = false) {
    if (reset) displayPage = 1;
    const grid = document.getElementById('productsGrid');
    const slice = filteredProducts.slice(0, displayPage * PAGE_SIZE);
    if (!filteredProducts.length) {
        grid.innerHTML = `
            <div style="grid-column:1/-1;text-align:center;padding:56px 16px;color:var(--text-muted)">
                <div style="font-size:56px;margin-bottom:12px">🔍</div>
                <p style="font-size:15px;font-weight:600">ምርቶቸ አልተገኙም</p>
                <p style="font-size:13px;margin-top:6px">ምድብ ደዉቶ ፍጥ ቅድ</p>
            </div>`;
        document.getElementById('loadMoreWrap').style.display = 'none';
        return;
    }
    grid.innerHTML = slice.map(p => `
        <a href="/app/product/${p.id}" class="product-card">
            <div class="product-image" style="height:140px;background:var(--bg);display:flex;align-items:center;justify-content:center;overflow:hidden">
                ${p.images && p.images[0]
                    ? `<img src="${safeUrl(p.images[0])}" alt="" style="width:100%;height:100%;object-fit:cover">`
                    : `<span style="font-size:52px">📦</span>`}
            </div>
            <div class="product-info">
                <p class="product-name" style="font-size:13px;line-height:1.35">${he(p.name)}</p>
                <div class="product-footer">
                    <span class="product-price" style="font-size:14px">ETB ${Number(p.price||0).toLocaleString()}</span>
                    ${p.stock_quantity <= 0 ? '<span style="font-size:10px;color:var(--danger)">አልቋል</span>' : ''}
                </div>
            </div>
        </a>
    `).join('');
    const hasMore = filteredProducts.length > displayPage * PAGE_SIZE;
    document.getElementById('loadMoreWrap').style.display = hasMore ? 'block' : 'none';
}

function filterByCat(catId, el) {
    activeCatId = catId;
    document.querySelectorAll('#homeCatGrid .category-card').forEach(c => c.classList.remove('active'));
    if (el) el.classList.add('active');
    filteredProducts = catId === null ? allProducts : allProducts.filter(p => p.category_id === catId);
    renderProductsPage(true);
}

function loadMore() {
    displayPage++;
    renderProductsPage();
}

function onGlobalSearch(val) {
    const q = val.trim().toLowerCase();
    filteredProducts = q
        ? allProducts.filter(p => p.name && p.name.toLowerCase().includes(q))
        : (activeCatId === null ? allProducts : allProducts.filter(p => p.category_id === activeCatId));
    renderProductsPage(true);
}

loadHomeCats();
loadProducts();
refreshAllBadges();
</script>
{% endblock %}

