    <h1 style="font-size:20px;font-weight:800">ዕቃዎቸ</h1>
</div>

<div class="cart-page">

    <!-- Empty state -->
    <div id="cartEmpty" class="cart-empty" style="display:none">
        <div style="font-size:80px;margin-bottom:20px">🛒</div>
        <p style="font-size:17px;font-weight:700;color:var(--text);margin-bottom:8px">ዕቃዎቸ ባይ ነው</p>
        <p style="font-size:13px;color:var(--text-muted);margin-bottom:28px">ምርቶቸን ዳሰሳ ወደ ቅርጫትዎ ያክሉ</p>
        <a href="/app/categories" class="btn-primary" style="display:inline-block;padding:14px 32px;width:auto;font-size:15px">
            ምርቶቸ ዳሰሳ →
        </a>
    </div>

    <!-- Cart items -->
    <div id="cartItems"></div>

    <!-- Summary -->
    <div class="cart-summary" id="cartSummary" style="display:none">
        <div class="cart-summary-row">
            <span>ንኡስ ድምር</span>
            <span id="cartSubtotal">ETB 0</span>
        </div>
        <div class="cart-summary-row">
            <span>🚚 ዲሊቨሪ</span>
            <span id="cartShipping">ETB 50</span>
        </div>
        <div class="cart-summary-row total">
            <span>ጠቅላላ</span>
            <strong id="cartTotal">ETB 0</strong>
        </div>
        <a href="/app/checkout" class="btn-primary" style="margin-top:16px">✅ ትዕዛዝ ስጡ</a>
    </div>
</div>

{% endblock %}

{% block scripts %}
<script>
function renderCart() {
    const items = cart.items;
    const emptyEl    = document.getElementById('cartEmpty');
    const itemsEl    = document.getElementById('cartItems');
    const summaryEl  = document.getElementById('cartSummary');

    if (!items.length) {
        emptyEl.style.display   = 'block';
        itemsEl.innerHTML       = '';
        summaryEl.style.display = 'none';
        return;
    }
    emptyEl.style.display   = 'none';
    summaryEl.style.display = 'block';

    itemsEl.innerHTML = items.map((item, idx) => `
        <div class="cart-item">
            <div class="cart-item-img">📦</div>
            <div class="cart-item-info">
                <p class="cart-item-name">${he(item.name)}</p>
                <p class="cart-item-price">ETB ${Number(item.price).toLocaleString()} × ${item.qty}</p>
            </div>
            <div class="cart-item-actions">
                <button onclick="changeQty(${item.id}, -1)" class="qty-btn" style="width:28px;height:28px;font-size:14px">−</button>
                <span style="min-width:24px;text-align:center;font-weight:700">${item.qty}</span>
                <button onclick="changeQty(${item.id}, 1)"  class="qty-btn" style="width:28px;height:28px;font-size:14px">+</button>
                <button onclick="removeFromCart(${item.id})" class="btn-remove">🗑</button>
            </div>
        </div>
    `).join('');

    const subtotal = cart.total();
    const shipping = subtotal >= 1000 ? 0 : 50;
    const total    = subtotal + shipping;
    document.getElementById('cartSubtotal').textContent = 'ETB ' + Number(subtotal).toLocaleString();
    document.getElementById('cartShipping').textContent = shipping === 0 ? 'ነፃ ✓' : 'ETB ' + shipping;
    document.getElementById('cartTotal').textContent    = 'ETB ' + Number(total).toLocaleString();
    refreshAllBadges();
}

function changeQty(productId, delta) {
    const item = cart.items.find(i => i.id === productId);
    if (!item) return;
    const newQty = item.qty + delta;
    if (newQty <= 0) {
        cart.remove(productId);
    } else {
        cart.updateQty(productId, newQty);
    }
    renderCart();
}

function removeFromCart(productId) {
    cart.remove(productId);
    renderCart();
}

renderCart();
</script>
{% endblock %}

{% extends "base.html" %}
{% block title %}ትዕዛዞቼ — ወሎዮ ሱቅ{% endblock %}

{% block content %}

<div style="background:linear-gradient(135deg,var(--primary) 0%,var(--primary-dark) 100%);padding:28px 16px 24px;text-align:center;color:white">
    <h1 style="font-size:22px;font-weight:800;margin-bottom:6px">📋 ትዕዛዞቼ</h1>
    <p style="font-size:13px;opacity:.85">የቅርብ ጊዜ ትዕዛዞቸዎን ይመልከቱ</p>
</div>

<div class="orders-list" id="ordersList">
    <div style="text-align:center;padding:40px;color:var(--text-muted)">እየጫናን ነው…</div>
</div>

{% endblock %}

{% block scripts %}
<script>
const STATUS_ICONS  = { pending:'⏳', confirmed:'✅', processing:'⚙️', shipped:'🚚', delivered:'📬', cancelled:'❌', refunded:'↩️' };
const STATUS_AM     = { pending:'በጥበቃ ላይ', confirmed:'ተረጋግጧል', processing:'በሂደት ላይ', shipped:'ተልኳል', delivered:'ደርሷል', cancelled:'ተሰርዟል', refunded:'ተመልሷል' };

async function loadOrders() {
    const tg = window.Telegram && window.Telegram.WebApp;
    const init_data = tg ? tg.initData : '';
    const el = document.getElementById('ordersList');
    try {
        const res = await fetch('/app/api/my-orders', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ init_data }),
        });
        const data = await res.json();
        if (!res.ok) {
            el.innerHTML = `
                <div style="text-align:center;padding:56px 16px;color:var(--text-muted)">
                    <div style="font-size:52px;margin-bottom:12px">📋</div>
                    <p style="font-size:15px;font-weight:600">ትዕዛዞቸን ለማየት<br>Telegram ከፍቶ ይጠቀሙ።</p>
                </div>`;
            return;
        }
        const orders = data.orders || [];
        if (!orders.length) {
            el.innerHTML = `
                <div style="text-align:center;padding:56px 16px;color:var(--text-muted)">
                    <div style="font-size:56px;margin-bottom:16px">📦</div>
                    <p style="font-size:16px;font-weight:700;color:var(--text);margin-bottom:8px">ምንም ትዕዛዞቸ የሉም</p>
                    <p style="font-size:13px;margin-bottom:24px">ምርቶቸን ዳሰሳ ትዕዛዝዎን ይጀምሩ</p>
                    <a href="/app/" class="btn-primary" style="display:inline-block;padding:12px 28px;width:auto">ዳሰሳ →</a>
                </div>`;
            return;
        }
        el.innerHTML = orders.map(o => {
            const icon   = STATUS_ICONS[o.status] || '📋';
            const statusAm = STATUS_AM[o.status] || o.status;
            const items  = (o.items || []).map(i => `<span class="order-item-chip">${he(i.name)} ×${i.quantity}</span>`).join('');
            const date   = o.created_at ? new Date(o.created_at).toLocaleDateString('am-ET') : '';
            return `
            <div class="order-card">
                <div class="order-header" onclick="this.parentElement.classList.toggle('expanded')">
                    <div class="order-meta">
                        <div class="order-number">#${he(o.order_number)}</div>
                        <div class="order-date">${date}</div>
                        ${o.shipping_city ? `<div class="order-city">📍 ${he(o.shipping_city)}</div>` : ''}
                    </div>
                    <div class="order-right">
                        <div class="order-total">ETB ${Number(o.total).toLocaleString()}</div>
                        <span style="font-size:12px;background:var(--primary-light);color:var(--primary);border-radius:999px;padding:3px 10px;font-weight:600">
                            ${icon} ${statusAm}
                        </span>
                    </div>
                </div>
                ${items ? `<div style="padding:0 16px 14px;display:flex;flex-wrap:wrap;gap:6px">${items}</div>` : ''}
                ${o.tracking_number ? `<div style="padding:0 16px 14px;font-size:12px;color:var(--text-muted)">🔍 ${he(o.tracking_number)}</div>` : ''}
            </div>`;
        }).join('');
    } catch(e) {
        el.innerHTML = '<p style="text-align:center;padding:40px;color:var(--text-muted)">ትዕዛዞቸ መጫን አልተቻለም።</p>';
    }
}

loadOrders();
refreshAllBadges();
</script>
{% endblock %}

{% extends "base.html" %}
{% block title %}ምርት — ወሎዮ ሱቅ{% endblock %}

{% block content %}

<div style="padding:12px 16px;display:flex;align-items:center;gap:8px;background:var(--white);border-bottom:1px solid var(--border)">
    <button onclick="history.back()" style="background:none;border:none;font-size:22px;cursor:pointer;padding:4px;color:var(--text)">‹</button>
    <span style="font-size:15px;font-weight:700" id="productBreadcrumb">ምርት</span>
</div>

<div id="productDetail" style="max-width:700px;margin:0 auto;padding:0 0 40px">
    <div style="text-align:center;padding:60px 16px;color:var(--text-muted)">እየጫናን ነው…</div>
</div>

{% endblock %}

{% block scripts %}
<script>
const productId = {{ product_id }};

async function loadProduct() {
    const el = document.getElementById('productDetail');
    try {
        const p = await fetch(`/app/api/product/${productId}`).then(r => {
            if (!r.ok) throw new Error('not found');
            return r.json();
        });

        document.getElementById('productBreadcrumb').textContent = p.name || 'ምርት';
        document.title = (p.name || 'ምርት') + ' — ወሎዮ ሱቅ';

        const inStock = p.stock_quantity > 0;
        const imgHtml = p.images && p.images[0]
            ? `<img src="${safeUrl(p.images[0])}" alt="" style="width:100%;max-height:340px;object-fit:cover">`
            : `<div style="height:260px;display:flex;align-items:center;justify-content:center;background:var(--bg);font-size:100px">📦</div>`;

        el.innerHTML = `
            <div>${imgHtml}</div>
            <div style="padding:20px 16px">
                <h1 style="font-size:20px;font-weight:800;line-height:1.35;margin-bottom:6px">${he(p.name)}</h1>
                ${p.name_am ? `<p style="font-size:14px;color:var(--text-muted);margin-bottom:10px">${he(p.name_am)}</p>` : ''}

                <div style="display:flex;align-items:baseline;gap:10px;margin-bottom:14px">
                    <span style="font-size:28px;font-weight:800;color:var(--primary)">ETB ${Number(p.price||0).toLocaleString()}</span>
                    ${p.compare_price && p.compare_price > p.price
                        ? `<span style="font-size:16px;text-decoration:line-through;color:var(--text-muted)">ETB ${Number(p.compare_price).toLocaleString()}</span>` : ''}
                </div>

                <span class="badge ${inStock ? 'badge-green' : 'badge-red'}" style="margin-bottom:18px;display:inline-flex">
                    ${inStock ? '✅ ምርቱ አለ (' + p.stock_quantity + ')' : '❌ አልቋል'}
                </span>

                ${p.description ? `<p style="font-size:14px;color:var(--text-muted);line-height:1.7;margin-bottom:20px">${he(p.description)}</p>` : ''}

                <div class="qty-control" style="margin-bottom:20px">
                    <span style="font-size:14px;font-weight:600;margin-right:8px">ብዛት:</span>
                    <button onclick="changeQty(-1)" class="qty-btn">−</button>
                    <span class="qty-value" id="qtyVal">1</span>
                    <button onclick="changeQty(1)"  class="qty-btn">+</button>
                </div>

                <button onclick="doAddToCart(${p.id}, ${JSON.stringify(he(p.name))}, ${p.price})"
                    class="btn-primary" ${!inStock ? 'disabled style="opacity:.5;cursor:not-allowed"' : ''}>
                    🛒 ወደ ቅርጫት ጨምር
                </button>
            </div>
        `;
    } catch(e) {
        el.innerHTML = `
            <div style="text-align:center;padding:60px 16px;color:var(--text-muted)">
                <div style="font-size:52px;margin-bottom:12px">❌</div>
                <p style="font-size:15px">ምርቱ አልተገኘም።</p>
                <a href="/app/" class="btn-primary" style="display:inline-block;margin-top:20px;padding:12px 28px;width:auto">ወደ ዋና ገጽ</a>
            </div>`;
    }
}

function changeQty(delta) {
    const el = document.getElementById('qtyVal');
    if (!el) return;
    el.textContent = Math.max(1, parseInt(el.textContent) + delta);
}

function doAddToCart(id, name, price) {
    const qty = parseInt(document.getElementById('qtyVal').textContent) || 1;
    cart.add({ id, name, price }, qty);
    refreshAllBadges();
}

loadProduct();
refreshAllBadges();
</script>
{% endblock %}

{% extends "base.html" %}
{% block title %}ትዕዛዝ ስጡ — ወሎዮ ሱቅ{% endblock %}

{% block content %}

<div style="padding:12px 16px;display:flex;align-items:center;gap:8px;background:var(--white);border-bottom:1px solid var(--border)">
    <button onclick="history.back()" style="background:none;border:none;font-size:22px;cursor:pointer;padding:4px;color:var(--text)">‹</button>
    <span style="font-size:15px;font-weight:700">ትዕዛዝ ስጡ</span>
</div>

<div class="checkout-page" id="checkoutPage">
    <!-- filled by JS if cart is not empty -->
</div>

{% endblock %}

{% block scripts %}
<script>
function renderCheckout() {
    const page = document.getElementById('checkoutPage');
    const items = cart.items;

    if (!items.length) {
        page.innerHTML = `
            <div style="text-align:center;padding:56px 16px;color:var(--text-muted)">
                <div style="font-size:64px;margin-bottom:16px">🛒</div>
                <p style="font-size:16px;font-weight:700;color:var(--text);margin-bottom:8px">ቅርጫቱ ባዶ ነው</p>
                <a href="/app/" class="btn-primary" style="display:inline-block;margin-top:16px;padding:12px 28px;width:auto">ምርቶቸ ዳሰሳ →</a>
            </div>`;
        return;
    }

    const subtotal = cart.total();
    const shipping = subtotal >= 1000 ? 0 : 50;
    const total    = subtotal + shipping;

    page.innerHTML = `
        <!-- Order Summary -->
        <div class="form-card">
            <h2>📦 የትዕዛዝ ዝርዝር</h2>
            ${items.map(i => `
                <div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border);font-size:14px">
                    <span>${he(i.name)} <span style="color:var(--text-muted)">×${i.qty}</span></span>
                    <span style="font-weight:600">ETB ${Number(i.price * i.qty).toLocaleString()}</span>
                </div>
            `).join('')}
            <div style="display:flex;justify-content:space-between;padding:10px 0 4px;font-size:14px;color:var(--text-muted)">
                <span>ንኡስ ድምር</span><span>ETB ${Number(subtotal).toLocaleString()}</span>
            </div>
            <div style="display:flex;justify-content:space-between;padding:4px 0;font-size:14px;color:var(--text-muted)">
                <span>ዲሊቨሪ</span><span>${shipping === 0 ? 'ነፃ ✓' : 'ETB ' + shipping}</span>
            </div>
            <div style="display:flex;justify-content:space-between;padding:10px 0 0;font-size:17px;font-weight:800;border-top:1px solid var(--border);margin-top:6px">
                <span>ጠቅላላ</span><span style="color:var(--primary)">ETB ${Number(total).toLocaleString()}</span>
            </div>
        </div>

        <!-- Delivery info -->
        <div class="form-card">
            <h2>📍 የማድረሻ መረጃ</h2>
            <div class="form-group">
                <label>ሙሉ ስም</label>
                <input type="text" id="fullName" placeholder="ስምዎን ያስገቡ">
            </div>
            <div class="form-group">
                <label>ስልክ ቁጥር</label>
                <input type="tel" id="phone" placeholder="09XXXXXXXX">
            </div>
            <div class="form-group">
                <label>ከተማ</label>
                <input type="text" id="city" placeholder="አዲስ አበባ" value="አዲስ አበባ">
            </div>
            <div class="form-group">
                <label>አድራሻ</label>
                <textarea id="address" rows="2" placeholder="ሙሉ አድራሻዎን ያስገቡ"></textarea>
            </div>
        </div>

        <!-- Payment method -->
        <div class="form-card">
            <h2>💳 የክፍያ መንገድ</h2>
            <label class="payment-option selected" onclick="selectPay('telebirr', this)">
                <input type="radio" name="pay" value="telebirr" checked>
                <span class="payment-icon">📱</span>
                <div><div class="payment-label">Telebirr</div><div class="payment-sub">የሞባይል ክፍያ</div></div>
            </label>
            <label class="payment-option" onclick="selectPay('cbe', this)">
                <input type="radio" name="pay" value="cbe">
                <span class="payment-icon">🏛</span>
                <div><div class="payment-label">CBE Birr</div><div class="payment-sub">ኮሜርሻል ባንክ</div></div>
            </label>
            <label class="payment-option" onclick="selectPay('chapa', this)">
                <input type="radio" name="pay" value="chapa">
                <span class="payment-icon">🏦</span>
                <div><div class="payment-label">Chapa</div><div class="payment-sub">Online Payment</div></div>
            </label>
            <label class="payment-option" onclick="selectPay('cod', this)">
                <input type="radio" name="pay" value="cod">
                <span class="payment-icon">💵</span>
                <div><div class="payment-label">Cash on Delivery</div><div class="payment-sub">ሲደርስ ይክፈሉ</div></div>
            </label>
        </div>

        <div id="orderError" class="alert alert-error" style="display:none"></div>

        <button id="placeOrderBtn" onclick="placeOrder(${total})" class="btn-primary" style="margin-bottom:16px">
            ✅ ትዕዛዝ አረጋግጥ — ETB ${Number(total).toLocaleString()}
        </button>
    `;
}

function selectPay(val, el) {
    document.querySelectorAll('.payment-option').forEach(o => o.classList.remove('selected'));
    el.classList.add('selected');
}

async function placeOrder(total) {
    const btn = document.getElementById('placeOrderBtn');
    const errEl = document.getElementById('orderError');
    errEl.style.display = 'none';

    const fullName = document.getElementById('fullName').value.trim();
    const phone    = document.getElementById('phone').value.trim();
    const city     = document.getElementById('city').value.trim();
    const address  = document.getElementById('address').value.trim();
    const payEl    = document.querySelector('input[name="pay"]:checked');
    const payment_method = payEl ? payEl.value : 'cod';

    if (!fullName || !phone || !address) {
        errEl.textContent = 'እባክዎ ሁሉም መስኮቸን ይሙሉ።';
        errEl.style.display = 'block';
        return;
    }

    btn.disabled = true;
    btn.textContent = '⏳ እየተሰራ ነው…';

    const tg = window.Telegram && window.Telegram.WebApp;
    const init_data = tg ? tg.initData : '';

    try {
        const res = await fetch('/app/api/checkout', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                init_data,
                items: cart.items.map(i => ({ id: i.id, name: i.name, price: i.price, qty: i.qty })),
                full_name: fullName,
                phone,
                city,
                address,
                payment_method,
            }),
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.detail || 'ስህተት ተከስቷል');

        cart.clear();
        refreshAllBadges();

        document.getElementById('checkoutPage').innerHTML = `
            <div style="text-align:center;padding:56px 16px">
                <div style="font-size:72px;margin-bottom:16px">✅</div>
                <h2 style="font-size:22px;font-weight:800;margin-bottom:8px">ትዕዛዝዎ ተቀብሏል!</h2>
                <p style="font-size:14px;color:var(--text-muted);margin-bottom:6px">
                    ትዕዛዝ ቁጥር: <strong style="color:var(--primary)">#${he(data.order_number)}</strong>
                </p>
                <p style="font-size:14px;color:var(--text-muted);margin-bottom:28px">
                    ጠቅላላ: <strong>ETB ${Number(data.total).toLocaleString()}</strong>
                </p>
                <a href="/app/orders" class="btn-primary" style="display:inline-block;padding:12px 28px;width:auto;margin-bottom:12px">ትዕዛዞቼን ይመልከቱ</a>
                <br>
                <a href="/app/" style="font-size:14px;color:var(--primary)">ወደ ዋና ገጽ →</a>
            </div>`;
    } catch(e) {
        errEl.textContent = e.message || 'ትዕዛዙ ሊተሰማ አልቻለም። እንደገና ይሞክሩ።';
        errEl.style.display = 'block';
        btn.disabled = false;
        btn.textContent = `✅ ትዕዛዝ አረጋግጥ — ETB ${Number(total).toLocaleString()}`;
    }
}

renderCheckout();
refreshAllBadges();
</script>
{% endblock %}

