            <div style="display:flex;justify-content:space-between;padding:10px 0 4px;font-size:14px;color:var(--text-muted)">
                <span>ንኡስ ድምር</span><span>ETB ${Number(subtotal).toLocaleString()}</span>
            </div>
            <div style="display:flex;justify-content:space-between;padding:4px 0;font-size:14px;color:var(--text-muted)">
                <span>ዲሊቨሪ</span><span>${shipping === 0 ? 'ነፃ ✓' : 'ETB ' + shipping}</span>
            </div>
            <div style="display:flex;justify-content:space-between;padding:10px 0 0;font-size:17px;font-weight:800;border-top:1px solid var(--border);margin-top:6px">
                <span>ጠቅላላ</span><span style="color:var(--primary)">ETB ${Number(total).toLocaleString()}</span>
            </div>
        </div>

        <div class="form-card">
            <h2>📍 የማድረሻ መረጃ</h2>
            <div class="form-group">
                <label>ሙሉ ስም</label>
                <input type="text" id="fullName" placeholder="ስምዎን ያስገቡ">
            </div>
            <div class="form-group">
                <label>ስልክ ቁጥር</label>
                <input type="tel" id="phone" placeholder="09XXXXXXXX">
            </div>
            <div class="form-group">
                <label>ከተማ</label>
                <input type="text" id="city" placeholder="አዲስ አበባ" value="አዲስ አበባ">
            </div>
            <div class="form-group">
                <label>አድራሻ</label>
                <textarea id="address" rows="2" placeholder="ሙሉ አድራሻዎን ያስገቡ"></textarea>
            </div>
        </div>

        <div class="form-card">
            <h2>💳 የክፍያ መንገድ</h2>
            <label class="payment-option selected" onclick="selectPay(this)">
                <input type="radio" name="pay" value="telebirr" checked>
                <span class="payment-icon">📱</span>
                <div><div class="payment-label">Telebirr</div><div class="payment-sub">የሞባይል ክፍያ</div></div>
            </label>
            <label class="payment-option" onclick="selectPay(this)">
                <input type="radio" name="pay" value="cbe">
                <span class="payment-icon">🏛</span>
                <div><div class="payment-label">CBE Birr</div><div class="payment-sub">ኮሜርሻል ባንክ</div></div>
            </label>
            <label class="payment-option" onclick="selectPay(this)">
                <input type="radio" name="pay" value="chapa">
                <span class="payment-icon">🏦</span>
                <div><div class="payment-label">Chapa</div><div class="payment-sub">Online Payment</div></div>
            </label>
            <label class="payment-option" onclick="selectPay(this)">
                <input type="radio" name="pay" value="cod">
                <span class="payment-icon">💵</span>
                <div><div class="payment-label">Cash on Delivery</div><div class="payment-sub">ሲደርስ ይክፈሉ</div></div>
            </label>
        </div>

        <div id="orderError" class="alert alert-error" style="display:none"></div>

        <button id="placeOrderBtn" onclick="placeOrder(${total})" class="btn-primary" style="margin-bottom:16px">
            ✅ ትዕዛዝ አረጋግጥ — ETB ${Number(total).toLocaleString()}
        </button>
    `;
}

function selectPay(el) {
    document.querySelectorAll('.payment-option').forEach(o => o.classList.remove('selected'));
    el.classList.add('selected');
}

async function placeOrder(total) {
    const btn   = document.getElementById('placeOrderBtn');
    const errEl = document.getElementById('orderError');
    errEl.style.display = 'none';

    const fullName       = document.getElementById('fullName').value.trim();
    const phone          = document.getElementById('phone').value.trim();
    const city           = document.getElementById('city').value.trim();
    const address        = document.getElementById('address').value.trim();
    const payEl          = document.querySelector('input[name="pay"]:checked');
    const payment_method = payEl ? payEl.value : 'cod';

    if (!fullName || !phone || !address) {
        errEl.textContent   = 'እባክዎ ሁሉም መስኮቸን ይሙሉ።';
        errEl.style.display = 'block';
        return;
    }

    btn.disabled    = true;
    btn.textContent = '⏳ እየተሰራ ነው…';

    const tg        = window.Telegram && window.Telegram.WebApp;
    const init_data = tg ? tg.initData : '';

    try {
        const res = await fetch('/app/api/checkout', {
            method:  'POST',
            headers: { 'Content-Type': 'application/json' },
            body:    JSON.stringify({
                init_data,
                items: cart.items.map(i => ({ id: i.id, name: i.name, price: i.price, qty: i.qty })),
                full_name: fullName,
                phone, city, address, payment_method,
            }),
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.detail || 'ስህተት ተከስቷል');

        cart.clear();
        refreshAllBadges();

        document.getElementById('checkoutPage').innerHTML = `
            <div style="text-align:center;padding:56px 16px">
                <div style="font-size:72px;margin-bottom:16px">✅</div>
                <h2 style="font-size:22px;font-weight:800;margin-bottom:8px">ትዕዛዝዎ ተቀብሏል!</h2>
                <p style="font-size:14px;color:var(--text-muted);margin-bottom:6px">
                    ትዕዛዝ ቁጥር: <strong style="color:var(--primary)">#${he(data.order_number)}</strong>
                </p>
                <p style="font-size:14px;color:var(--text-muted);margin-bottom:28px">
                    ጠቅላላ: <strong>ETB ${Number(data.total).toLocaleString()}</strong>
                </p>
                <a href="/app/orders" class="btn-primary" style="display:inline-block;padding:12px 28px;width:auto;margin-bottom:12px">ትዕዛዞቼን ይመልከቱ</a>
                <br><a href="/app/" style="font-size:14px;color:var(--primary);display:inline-block;margin-top:12px">ወደ ዋና ገጽ →</a>
            </div>`;
    } catch(e) {
        errEl.textContent   = e.message || 'ትዕዛዙ ሊተሰማ አልቻለም። እንደገና ይሞክሩ።';
        errEl.style.display = 'block';
        btn.disabled        = false;
        btn.textContent     = `✅ ትዕዛዝ አረጋግጥ — ETB ${Number(total).toLocaleString()}`;
    }
}

renderCheckout();
refreshAllBadges();
</script>
{% endblock %}

