@web_app_router.get("/api/products")
async def get_products(
    page: int = 1,
    page_size: int = 20,
    db=Depends(get_db_session),
):
    """Get products for web app."""
    product_service = ProductService(db)
    products, total = await product_service.product_repo.get_all_with_count(
        limit=page_size,
        offset=(page - 1) * page_size,
    )
    return {
        "items": [p.to_dict() for p in products],
        "total": total,
        "page": page,
        "page_size": page_size,
    }


@web_app_router.get("/api/search")
async def search_products(q: str = "", limit: int = 6, db=Depends(get_db_session)):
    """
    Autocomplete / search endpoint.
    Returns up to `limit` products whose name or Amharic name contains `q` (case-insensitive).
    """
    from sqlalchemy import select, or_, func
    from apps.products.models import Product

    q = q.strip()
    if not q:
        return {"items": [], "query": q}

    pattern = f"%{q}%"
    stmt = (
        select(Product)
        .where(
            Product.is_deleted == False,
            Product.is_active == True,
            or_(
                func.lower(Product.name).like(func.lower(pattern)),
                func.lower(func.coalesce(Product.name_am, "")).like(func.lower(pattern)),
            ),
        )
        .order_by(Product.name)
        .limit(limit)
    )
    result = await db.execute(stmt)
    products = result.scalars().all()

    return {
        "items": [
            {
                "id": p.id,
                "name": p.name,
                "name_am": getattr(p, "name_am", "") or "",
                "price": float(p.price),
                "category": p.category.name if p.category else "",
                "image_url": (p.images[0] if p.images else "") if hasattr(p, "images") and p.images else "",
            }
            for p in products
        ],
        "query": q,
    }

