// ── Search autocomplete ──────────────────────────────────────
const _sdrop = {
    el:      null,
    input:   null,
    timer:   null,
    items:   [],
    focused: -1,

    init() {
        this.el    = document.getElementById('searchDropdown');
        this.input = document.getElementById('globalSearch');
        // Close when clicking outside
        document.addEventListener('click', e => {
            if (!this.el || !this.input) return;
            if (!this.el.contains(e.target) && e.target !== this.input) {
                this.close();
            }
        });
    },

    open()  { this.el && this.el.classList.add('open'); },
    close() { this.el && this.el.classList.remove('open'); this.focused = -1; },

    async fetch(q) {
        try {
            const data = await fetch(`/app/api/search?q=${encodeURIComponent(q)}&limit=6`).then(r => r.json());
            return data.items || [];
        } catch(e) { return []; }
    },

    render(items, q) {
        this.items   = items;
        this.focused = -1;
        if (!items.length) {
            this.el.innerHTML = `<div class="sdrop-empty">🔍 "${he(q)}" — ምንም ምርት አልተገኘም</div>`;
        } else {
            this.el.innerHTML =
                items.map((p, i) => {
                    const thumb = p.image_url
                        ? `<img src="${safeUrl(p.image_url)}" alt="">`
                        : '📦';
                    const meta = [p.name_am, p.category].filter(Boolean).join(' · ');
                    return `
                    <a class="sdrop-item" href="/app/product/${p.id}" onclick="_sdrop.close()">
                        <div class="sdrop-thumb">${thumb}</div>
                        <div style="min-width:0;flex:1">
                            <div class="sdrop-name">${he(p.name)}</div>
                            ${meta ? `<div class="sdrop-meta">${he(meta)}</div>` : ''}
                        </div>
                        <div class="sdrop-price">ETB ${Number(p.price).toLocaleString()}</div>
                    </a>`;
                }).join('') +
                `<div class="sdrop-footer" onclick="_sdrop.goSearch()">
                    ሁሉንም ውጤቶቸ ይምልከቱ →
                </div>`;
        }
        this.open();
    },

    navigate(dir) {
        const rows = this.el ? this.el.querySelectorAll('.sdrop-item') : [];
        if (!rows.length) return;
        rows[this.focused]?.classList.remove('focused');
        this.focused = Math.max(-1, Math.min(rows.length - 1, this.focused + dir));
        rows[this.focused]?.classList.add('focused');
        rows[this.focused]?.scrollIntoView({ block: 'nearest' });
    },

    selectFocused() {
        const rows = this.el ? this.el.querySelectorAll('.sdrop-item') : [];
        if (this.focused >= 0 && rows[this.focused]) {
            rows[this.focused].click();
        } else {
            this.goSearch();
        }
    },

    goSearch() {
        const q = this.input ? this.input.value.trim() : '';
        if (q) window.location.href = `/app/?q=${encodeURIComponent(q)}`;
        this.close();
    },
};

function onGlobalSearch(val) {
    clearTimeout(_sdrop.timer);
    const q = val.trim();
    if (!q) { _sdrop.close(); return; }
    _sdrop.timer = setTimeout(async () => {
        const items = await _sdrop.fetch(q);
        _sdrop.render(items, q);
    }, 280);
}

function onSearchKeydown(e) {
    const dd = document.getElementById('searchDropdown');
    if (!dd || !dd.classList.contains('open')) {
        if (e.key === 'Enter') _sdrop.goSearch();
        return;
    }
    if (e.key === 'ArrowDown')  { e.preventDefault(); _sdrop.navigate(1); }
    else if (e.key === 'ArrowUp')   { e.preventDefault(); _sdrop.navigate(-1); }
    else if (e.key === 'Enter')     { e.preventDefault(); _sdrop.selectFocused(); }
    else if (e.key === 'Escape')    { _sdrop.close(); }
}

function sdropOpen() { _sdrop.open(); }

// Init all badges and autocomplete on load
document.addEventListener('DOMContentLoaded', () => {
    refreshAllBadges();
    _sdrop.init();
});

