{% extends "base.html" %}
{% block title %}ወሎዮ ሱቅ 🇪🇹{% endblock %}

{% block content %}

<!-- ── Promo Banners ───────────────────────────────────────────── -->
<div class="promo-scroll">
    <div class="promo-card">
        <div class="promo-text">
            <h3>እስከ 30% ቅናሽ!</h3>
            <p>ምርጥ ምርቶቸን አሁን ዳሰሳ</p>
        </div>
        <a href="/app/categories" class="promo-btn">ዳሰሳ →</a>
    </div>
    <div class="promo-card promo-gold">
        <div class="promo-text">
            <h3>1ኛ ትዕዛዝ ቅናሽ</h3>
            <p>ከETB 1,000 በላይ ነፃ ዲሊቨሪ</p>
        </div>
        <a href="/app/categories" class="promo-btn">ግዛ →</a>
    </div>
</div>

<!-- ── Categories Row ─────────────────────────────────────────── -->
<div class="section" style="padding-bottom:0">
    <div class="section-title">
        📦 ምድቦቸ
        <a href="/app/categories" style="margin-left:auto;font-size:13px;font-weight:600;color:var(--primary);text-decoration:none">ሁሉ ምርቶቸ →</a>
    </div>
    <div class="category-grid" id="homeCatGrid">
        <div style="grid-column:1/-1;text-align:center;padding:12px;color:var(--text-muted);font-size:13px">እየጫናን…</div>
    </div>
</div>

<!-- ── Products ───────────────────────────────────────────────── -->
<div class="section">
    <div class="section-title" id="productsSectionTitle">🛒 ምርቶቸ</div>
    <div class="products-grid" id="productsGrid" style="grid-template-columns:repeat(2,1fr);gap:12px">
        <div style="grid-column:1/-1;text-align:center;padding:40px;color:var(--text-muted)">
            ምርቶቸ እየጫናን ነው…
        </div>
    </div>
    <div id="loadMoreWrap" style="text-align:center;margin-top:18px;display:none">
        <button id="loadMoreBtn" onclick="loadMoreProds()" class="btn-primary" style="width:auto;padding:12px 36px">
            ተጨማሪ ምርቶቸ
        </button>
    </div>
</div>

{% endblock %}

{% block scripts %}
<script>
// ── Category icon map ────────────────────────────────────────────
const CAT_ICONS = {
    'electronics':'📱','clothing':'👕','food':'🍎','food & drinks':'🍎',
    'books':'📚','beauty':'💄','health':'💊','home':'🏠','home & living':'🏠',
    'sports':'⚽','toys':'🧸','automotive':'🚗','agriculture':'🌾',
};
function catIcon(name) {
    if (!name) return '🛍️';
    const k = name.toLowerCase();
    return CAT_ICONS[k] || Object.keys(CAT_ICONS).reduce(
        (f, key) => (!f && k.includes(key)) ? CAT_ICONS[key] : f, '') || '🛍️';
}

// ── State ────────────────────────────────────────────────────────
let allProds = [];
let filteredProds = [];
let activeCatId = null;
let displayPage = 1;
const PAGE_SIZE = 20;

// ── Read URL params ──────────────────────────────────────────────
const _urlParams = new URLSearchParams(window.location.search);
const _initQ   = (_urlParams.get('q') || '').trim();
const _initCat = _urlParams.get('category') ? parseInt(_urlParams.get('category')) : null;

// ── Render product cards ─────────────────────────────────────────
function renderProds(reset) {
    if (reset) displayPage = 1;
    const grid = document.getElementById('productsGrid');

    if (!filteredProds.length) {
        grid.innerHTML = `
            <div style="grid-column:1/-1;text-align:center;padding:56px 16px;color:var(--text-muted)">
                <div style="font-size:56px;margin-bottom:12px">🔍</div>
                <p style="font-size:15px;font-weight:600;color:var(--text)">ምርቶቸ አልተገኙም</p>
                <p style="font-size:13px;margin-top:6px">ሌሎቸ ምድቦቸ ይሞክሩ</p>
            </div>`;
        document.getElementById('loadMoreWrap').style.display = 'none';
        return;
    }

    const slice = filteredProds.slice(0, displayPage * PAGE_SIZE);
    grid.innerHTML = slice.map(p => {
        const thumb = (p.images && p.images.length)
            ? `<img src="${safeUrl(p.images[0])}" alt="" style="width:100%;height:100%;object-fit:cover">`
            : `<span style="font-size:52px">📦</span>`;
        const outOfStock = p.stock_quantity <= 0;
        const nameAm = p.name_am ? `<div style="font-size:11px;color:var(--text-muted);margin-bottom:2px">${he(p.name_am)}</div>` : '';
        return `
        <div class="product-card" onclick="window.location.href='/app/product/${p.id}'">
            <div class="product-image" style="height:140px;background:var(--bg);display:flex;align-items:center;justify-content:center;overflow:hidden;cursor:pointer">
                ${thumb}
            </div>
            <div class="product-info" style="padding:10px 10px 12px">
                ${nameAm}
                <p class="product-name" style="font-size:13px;line-height:1.35;margin-bottom:6px">${he(p.name)}</p>
                <div class="product-footer" style="gap:6px">
                    <span class="product-price" style="font-size:14px">ETB ${Number(p.price).toLocaleString()}</span>
                    ${outOfStock
                        ? `<span style="font-size:10px;color:var(--danger);font-weight:600">አልቋል</span>`
                        : `<button class="btn-add" style="padding:5px 10px;font-size:11px"
                              onclick="event.stopPropagation();addCard(${p.id},'${he(p.name).replace(/'/g,"\\'")}',${p.price})">
                              🛒 ጨምር
                           </button>`}
                </div>
            </div>
        </div>`;
    }).join('');

    document.getElementById('loadMoreWrap').style.display =
        filteredProds.length > displayPage * PAGE_SIZE ? 'block' : 'none';
}

function addCard(id, name, price) {
    cart.add({ id, name, price });
    refreshAllBadges();
}

function loadMoreProds() {
    displayPage++;
    renderProds(false);
}

// ── Filter by category ───────────────────────────────────────────
function filterByCat(catId, el) {
    activeCatId = catId;
    document.querySelectorAll('#homeCatGrid .category-card').forEach(c => c.classList.remove('active'));
    if (el) el.classList.add('active');

    // Also clear search bar
    const searchEl = document.getElementById('globalSearch');
    if (searchEl) searchEl.value = '';
    _sdrop.close();

    applyFilters(null);
}

// ── Apply current search + category ────────────────────────────
function applyFilters(q) {
    const searchQ = (q !== null ? q : (document.getElementById('globalSearch')?.value || '')).trim().toLowerCase();
    let base = activeCatId !== null
        ? allProds.filter(p => p.category_id === activeCatId)
        : allProds;
    filteredProds = searchQ
        ? base.filter(p => (p.name || '').toLowerCase().includes(searchQ) || (p.name_am || '').toLowerCase().includes(searchQ))
        : base;
    const title = document.getElementById('productsSectionTitle');
    if (title) {
        if (searchQ) title.textContent = `🔍 "${searchQ}" ውጤቶቸ`;
        else if (activeCatId) title.textContent = '🛒 ምርቶቸ';
        else title.textContent = '🛒 ሁሉ ምርቶቸ';
    }
    renderProds(true);
}

// ── Override global search for home page ────────────────────────
function onGlobalSearch(val) {
    clearTimeout(_sdrop.timer);
    _sdrop.close();
    applyFilters(val);
}

// ── Load categories mini-strip ──────────────────────────────────
async function loadHomeCats() {
    const grid = document.getElementById('homeCatGrid');
    try {
        const cats = await fetch('/app/api/categories').then(r => r.json());
        const items = [{ id: null, name: 'ሁሉ', name_am: '' }, ...cats];
        grid.innerHTML = items.map(c => {
            const isAll = c.id === null;
            const isActive = isAll ? activeCatId === null : c.id === activeCatId;
            const label = isAll ? 'ሁሉ' : he(c.name_am || c.name);
            const icon  = isAll ? '🛍️' : catIcon(c.name);
            const cid   = isAll ? 'null' : c.id;
            return `
            <div class="category-card${isActive ? ' active' : ''}" onclick="filterByCat(${cid},this)">
                <div class="icon">${icon}</div>
                <div class="label">${label}</div>
            </div>`;
        }).join('');
    } catch(e) {
        grid.innerHTML = '';
    }
}

// ── Load products ───────────────────────────────────────────────
async function loadHomeProds() {
    const grid = document.getElementById('productsGrid');
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:40px;color:var(--text-muted)">ምርቶቸ እየጫናን ነው…</div>';
    try {
        // Fetch all products (up to 200); let client handle filtering
        const url = '/app/api/products?page_size=200&page=1';
        const resp = await fetch(url, { cache: 'no-store' });
        if (!resp.ok) throw new Error('HTTP ' + resp.status);
        const data = await resp.json();
        allProds = Array.isArray(data.items) ? data.items : [];

        // Apply initial URL params
        if (_initCat !== null) {
            activeCatId = _initCat;
            // Highlight the matching category card (if already rendered)
            document.querySelectorAll('#homeCatGrid .category-card').forEach((el, i) => {
                el.classList.toggle('active', i > 0 && /* rough match */ false);
            });
        }
        if (_initQ) {
            const searchEl = document.getElementById('globalSearch');
            if (searchEl) searchEl.value = _initQ;
        }
        applyFilters(_initQ || null);
    } catch(e) {
        grid.innerHTML = `
            <div style="grid-column:1/-1;text-align:center;padding:40px 16px;color:var(--text-muted)">
                <div style="font-size:48px;margin-bottom:12px">⚠️</div>
                <p style="font-size:14px;font-weight:600">ምርቶቸ መጫን አልተቻለም</p>
                <button onclick="loadHomeProds()" class="btn-primary" style="margin-top:16px;width:auto;padding:10px 24px;font-size:14px">
                    እንደገና ሞክር
                </button>
            </div>`;
    }
}

// ── Boot ─────────────────────────────────────────────────────────
(async function boot() {
    // Fetch categories and products in parallel
    await Promise.all([loadHomeCats(), loadHomeProds()]);
    refreshAllBadges();
})();
</script>
{% endblock %}

{% extends "base.html" %}
{% block title %}ምርት — ወሎዮ ሱቅ{% endblock %}

{% block content %}

<div style="padding:12px 16px;display:flex;align-items:center;gap:8px;background:var(--white);border-bottom:1px solid var(--border);position:sticky;top:56px;z-index:90">
    <button onclick="history.back()" style="background:none;border:none;font-size:24px;cursor:pointer;padding:4px 8px;color:var(--text);line-height:1">‹</button>
    <span style="font-size:15px;font-weight:700;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" id="productBreadcrumb">ምርት</span>
    <a href="/app/cart" style="position:relative;font-size:22px;text-decoration:none">
        🛒<span class="cart-badge" id="navCartBadge2" style="display:none;position:absolute;top:-4px;right:-6px;background:var(--danger);color:white;border-radius:999px;font-size:9px;min-width:16px;height:16px;display:none;align-items:center;justify-content:center;font-weight:700;padding:0 3px">0</span>
    </a>
</div>

<div id="productDetail" style="max-width:700px;margin:0 auto;padding-bottom:40px">
    <div style="text-align:center;padding:60px 16px;color:var(--text-muted)">
        <div style="font-size:40px;margin-bottom:12px">⏳</div>
        <p>እየጫናን ነው…</p>
    </div>
</div>

{% endblock %}

{% block scripts %}
<script>
const _pid = {{ product_id }};
let _qty = 1;
let _prod = null;

async function loadProduct() {
    const el = document.getElementById('productDetail');
    try {
        const resp = await fetch(`/app/api/product/${_pid}`, { cache: 'no-store' });
        if (!resp.ok) throw new Error('not found');
        _prod = await resp.json();

        const name   = _prod.name || '';
        const nameAm = _prod.name_am || '';
        const price  = Number(_prod.price || 0);
        const cmpP   = _prod.compare_price ? Number(_prod.compare_price) : null;
        const stock  = Number(_prod.stock_quantity || 0);
        const inStock = stock > 0;
        const imgs   = _prod.images || [];
        const desc   = _prod.description || _prod.description_am || '';

        document.getElementById('productBreadcrumb').textContent = name || 'ምርት';
        document.title = (name || 'ምርት') + ' — ወሎዮ ሱቅ';

        const thumbHtml = imgs.length && imgs[0]
            ? `<img src="${safeUrl(imgs[0])}" alt="${he(name)}" style="width:100%;height:100%;object-fit:cover;display:block">`
            : `<div style="height:260px;display:flex;align-items:center;justify-content:center;font-size:100px;background:var(--bg)">📦</div>`;

        const discountPct = (cmpP && cmpP > price)
            ? Math.round((cmpP - price) / cmpP * 100)
            : null;

        el.innerHTML = `
            <!-- Image -->
            <div style="background:var(--bg);overflow:hidden${imgs.length ? ';aspect-ratio:1' : ';height:260px'}">
                ${thumbHtml}
            </div>

            <div style="padding:18px 16px 8px">
                <!-- Name -->
                <h1 style="font-size:20px;font-weight:800;line-height:1.35;margin-bottom:${nameAm ? '4px' : '10px'}">${he(name)}</h1>
                ${nameAm ? `<p style="font-size:14px;color:var(--text-muted);margin-bottom:10px">${he(nameAm)}</p>` : ''}

                <!-- Price -->
                <div style="display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:12px">
                    <span style="font-size:28px;font-weight:800;color:var(--primary)">ETB ${price.toLocaleString()}</span>
                    ${cmpP && cmpP > price ? `
                        <span style="font-size:15px;text-decoration:line-through;color:var(--text-muted)">ETB ${cmpP.toLocaleString()}</span>
                        <span style="font-size:12px;font-weight:700;background:#fef3c7;color:#92400e;padding:2px 8px;border-radius:999px">-${discountPct}%</span>
                    ` : ''}
                </div>

                <!-- Stock badge -->
                <div style="margin-bottom:18px">
                    <span class="badge ${inStock ? 'badge-green' : 'badge-red'}">
                        ${inStock ? '✅ ምርቱ አለ' + (stock < 20 ? ' (' + stock + ' ቀረ)' : '') : '❌ አልቋል'}
                    </span>
                </div>

                <!-- Description -->
                ${desc ? `<p style="font-size:14px;color:var(--text-muted);line-height:1.75;margin-bottom:20px">${he(desc)}</p>` : ''}

                <!-- Qty control -->
                ${inStock ? `
                <div style="display:flex;align-items:center;gap:12px;margin-bottom:20px">
                    <span style="font-size:14px;font-weight:600;color:var(--text-muted)">ብዛት</span>
                    <div style="display:flex;align-items:center;gap:8px;background:var(--bg);border-radius:10px;padding:4px">
                        <button onclick="changeQty(-1)" class="qty-btn">−</button>
                        <span id="qtyVal" style="font-size:18px;font-weight:700;min-width:28px;text-align:center">1</span>
                        <button onclick="changeQty(1)" class="qty-btn">+</button>
                    </div>
                </div>
                <button onclick="doAddToCart()" class="btn-primary" id="addCartBtn">
                    🛒 ወደ ቅርጫት ጨምር
                </button>
                <a href="/app/cart" class="btn-primary" id="goCartBtn" style="display:none;background:var(--primary-dark);margin-top:10px">
                    ✅ ቅርጫቴን ይምልከቱ →
                </a>
                ` : `
                <button class="btn-primary" disabled style="opacity:.45;cursor:not-allowed">
                    ❌ አልቋል
                </button>
                `}
            </div>

            <!-- Related / back -->
            <div style="padding:16px 16px 8px;border-top:1px solid var(--border);margin-top:8px">
                <a href="/app/" style="font-size:13px;color:var(--primary);font-weight:600;text-decoration:none">‹ ወደ ምርቶቸ ዝርዝር</a>
            </div>
        `;
    } catch(e) {
        el.innerHTML = `
            <div style="text-align:center;padding:60px 16px;color:var(--text-muted)">
                <div style="font-size:52px;margin-bottom:14px">❌</div>
                <p style="font-size:16px;font-weight:700;color:var(--text);margin-bottom:8px">ምርቱ አልተገኘም</p>
                <a href="/app/" class="btn-primary" style="display:inline-block;margin-top:16px;padding:12px 28px;width:auto">ወደ ዋና ገጽ →</a>
            </div>`;
    }
}

function changeQty(delta) {
    _qty = Math.max(1, _qty + delta);
    const el = document.getElementById('qtyVal');
    if (el) el.textContent = _qty;
}

function doAddToCart() {
    if (!_prod) return;
    cart.add({ id: _prod.id, name: _prod.name, price: Number(_prod.price) }, _qty);
    refreshAllBadges();
    // Show "go to cart" button
    const addBtn  = document.getElementById('addCartBtn');
    const cartBtn = document.getElementById('goCartBtn');
    if (addBtn)  addBtn.style.display  = 'none';
    if (cartBtn) cartBtn.style.display = 'block';
}

loadProduct();
refreshAllBadges();
</script>
{% endblock %}
